package dev.matchlab;import java.util.*;
public final class TelemetryWindow {public List<List<TelemetryAnalyzer.Sample>> byCycle(List<TelemetryAnalyzer.Sample> samples){var grouped=new TreeMap<Integer,List<TelemetryAnalyzer.Sample>>();samples.forEach(s->grouped.computeIfAbsent(s.cycle(),k->new ArrayList<>()).add(s));return grouped.values().stream().map(List::copyOf).toList();}public List<TelemetryAnalyzer.Sample> between(List<TelemetryAnalyzer.Sample> samples,long start,long end){if(end<start)throw new IllegalArgumentException("invalid time window");return samples.stream().filter(s->s.ms()>=start&&s.ms()<=end).toList();}}
